using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using UnityEditor;using UnityEngine;using Newtonsoft.Json;
public static class FinishModelFolders {public static string Main(){var deleted=new List<string>();AssetDatabase.StartAssetEditing();try{foreach(var root in new[]{"Assets/Afrer_Seconds/05.Model","Assets/Afrer_Seconds/03.Art/Candidates/VARCO"})foreach(var d in AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith(root+"/")&&AssetDatabase.IsValidFolder(p)).OrderByDescending(p=>p.Length).ToArray()){bool keep=Regex.IsMatch(d,@"05\.Model/(Player|Enemy)$")||Regex.IsMatch(d,@"05\.Model/(Props|Environment)$")||Regex.IsMatch(d,@"05\.Model/(Player|Enemy)/(Materials|Textures)$")||Regex.IsMatch(d,@"05\.Model/(Props|Environment)/(B[1-5]|1F|Common)(/(Materials|Textures))?$");if(!keep&&Directory.Exists(d)&&!Directory.EnumerateFileSystemEntries(d).Any()){if(!AssetDatabase.DeleteAsset(d))throw new Exception("Cannot remove empty directory "+d);deleted.Add(d);}}}finally{AssetDatabase.StopAssetEditing();}AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var unexpected=AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith("Assets/Afrer_Seconds/05.Model/")&&AssetDatabase.IsValidFolder(p)&&!Regex.IsMatch(p,@"05\.Model/(Player|Enemy)(/(Materials|Textures))?$")&&!Regex.IsMatch(p,@"05\.Model/(Props|Environment)(/(B[1-5]|1F|Common)(/(Materials|Textures))?)?$")).ToArray();if(unexpected.Length>0)throw new Exception("Unexpected folders "+string.Join(",",unexpected));string r=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/ModelFolderCleanup_20261103"));File.WriteAllText(r+"/folder_cleanup.json",JsonConvert.SerializeObject(new{emptyFoldersRemoved=deleted,unexpectedFolders=unexpected},Formatting.Indented));return "Removed "+deleted.Count+" additional empty folders; only requested layout remains";}}
